/* AdminSchedule_SQL.updateFinshNoticeList */
UPDATE TB_NOTICE_INFO
     SET NOTICE_FINISH_YN = 'Y'
         , NOTICE_FIX_YN = 'N'
         , NOTICE_POP_YN = 'N'
     	 , UPD_ID = #{updId}
		 , UPD_DT = NOW()
 WHERE 1=1
    AND NOTICE_ID = #{noticeId}

/* AdminSchedule_SQL.updateEndMoimList */
UPDATE TB_MOIM_INFO
     SET MOIM_STATUS_YN = 'N'
     	 , UPD_ID = #{updId}
		 , UPD_DT = NOW()
 WHERE 1=1
    AND MOIM_ID = #{moimId}
